/* Local shim for Magnific Popup
   Replace with the official minified file to serve locally.
*/
(function(){
  if(typeof window === 'undefined') return;
  try{ if(window.jQuery && jQuery.magnificPopup) return; }catch(e){}
  var cdn = 'https://cdnjs.cloudflare.com/ajax/libs/magnific-popup.js/1.1.0/jquery.magnific-popup.min.js';
  var s=document.createElement('script'); s.type='text/javascript'; s.async=true; s.src=cdn; document.head.appendChild(s);
})();
